export const TERMINAL_WIDTH = 960;
export const TERMINAL_HEIGHT = 540;
export const WORLD_ZONE_SIZE = 960;
export const COLORS = { dark: "#222323", light: "#f0f6f0" };
export const INITIAL_PLAYER_LIVES = 6;

const PLAYER_SPEED = 175;
const BULLET_SPEED = 430;
const TILE_SIZE = 32;
const ENEMY_SIZE = 16;
const ENEMY_BULLET_SIZE = 7;
const TANK_SHELL_RANGE = 320;
const EXPLOSION_FRAME_DURATION = 0.075;
const EXPLOSION_FRAME_COUNT = 6;
const PLANE_SPEED = 500;
const PLANE_BOMB_DURATION = 0.9;
const DECOR_ASSETS = [
  "decorBarbelerHorizontal", "decorBarbelerVertical", "decorBlocAntichar",
  "decorFlaque1", "decorFlaque2", "decorFlaque3",
  "decorMitrailletteDroite", "decorMitrailletteGauche",
];
const directionVectors = {
  up: { x: 0, y: -1 }, right: { x: 1, y: 0 }, down: { x: 0, y: 1 }, left: { x: -1, y: 0 },
};

function hashCoordinates(x, y, salt = 0) {
  let value = Math.imul(x ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(y ^ salt, 0xc2b2ae35);
  value ^= value >>> 16;
  return value >>> 0;
}

function zoneKey(x, y) { return `${x},${y}`; }
function worldZone(value) { return Math.floor(value / WORLD_ZONE_SIZE); }

function createEnemy(zoneX, zoneY, index, localX, localY, formation = false) {
  const seed = hashCoordinates(zoneX, zoneY, index + 90);
  return {
    id: `${zoneKey(zoneX, zoneY)}-${index}`,
    x: zoneX * WORLD_ZONE_SIZE + localX,
    y: zoneY * WORLD_ZONE_SIZE + localY,
    facing: "down",
    cooldown: 0.8 + (hashCoordinates(zoneX, zoneY, index + 40) % 120) / 100,
    alive: true,
    corpse: false,
    formation,
    patrolAxis: seed & 1 ? "x" : "y",
    patrolDirection: seed & 2 ? 1 : -1,
    strafeDirection: seed & 4 ? 1 : -1,
    moveDirection: seed & 1 ? (seed & 2 ? "right" : "left") : (seed & 2 ? "down" : "up"),
    behavior: "patrol",
    decisionTimer: 0,
    shotAnimation: 0,
    blockedShot: false,
  };
}

function createDecor(zoneX, zoneY, enemies) {
  const decor = [];
  const occupied = new Set();
  const count = 30 + (hashCoordinates(zoneX, zoneY, 301) % 15);
  let attempt = 0;
  while (decor.length < count && attempt < 180) {
    const seed = hashCoordinates(zoneX * 31 + attempt, zoneY * 37 - attempt, 700 + attempt);
    const tileX = 1 + (seed % 28);
    const tileY = 1 + ((seed >>> 7) % 28);
    const key = `${tileX},${tileY}`;
    const x = zoneX * WORLD_ZONE_SIZE + tileX * TILE_SIZE;
    const y = zoneY * WORLD_ZONE_SIZE + tileY * TILE_SIZE;
    const centerX = x + TILE_SIZE / 2;
    const centerY = y + TILE_SIZE / 2;
    const nearInitialPlayer = zoneX === 0 && zoneY === 0 && Math.hypot(centerX - 480, centerY - 480) < 120;
    const nearEnemy = enemies.some((enemy) => Math.hypot(centerX - enemy.x, centerY - enemy.y) < 42);
    if (!occupied.has(key) && !nearInitialPlayer && !nearEnemy) {
      occupied.add(key);
      decor.push({
        id: `${zoneKey(zoneX, zoneY)}-decor-${decor.length}`,
        x,
        y,
        asset: DECOR_ASSETS[(seed >>> 13) % DECOR_ASSETS.length],
        crushed: false,
      });
    }
    attempt += 1;
  }
  return decor;
}

function createHealthBonuses(zoneX, zoneY, seed, enemies, decor) {
  if (!(zoneX === 0 && zoneY === 0) && seed % 2 !== 0) return [];
  for (let attempt = 0; attempt < 60; attempt += 1) {
    const positionSeed = hashCoordinates(zoneX + attempt, zoneY - attempt, seed + 1200);
    const tileX = 2 + (positionSeed % 26);
    const tileY = 2 + ((positionSeed >>> 8) % 26);
    const x = zoneX * WORLD_ZONE_SIZE + tileX * TILE_SIZE + TILE_SIZE / 2;
    const y = zoneY * WORLD_ZONE_SIZE + tileY * TILE_SIZE + TILE_SIZE / 2;
    const awayFromPlayer = !(zoneX === 0 && zoneY === 0) || Math.hypot(x - 480, y - 480) > 150;
    const awayFromEnemies = enemies.every((enemy) => Math.hypot(x - enemy.x, y - enemy.y) > 48);
    const awayFromDecor = decor.every((item) => Math.hypot(x - (item.x + 16), y - (item.y + 16)) > 40);
    if (awayFromPlayer && awayFromEnemies && awayFromDecor) {
      return [{ id: `${zoneKey(zoneX, zoneY)}-health`, x, y, collected: false }];
    }
  }
  return [];
}

function createZone(zoneX, zoneY) {
  const seed = hashCoordinates(zoneX, zoneY, 17);
  const isStartingZone = zoneX === 0 && zoneY === 0;
  const hasEnemies = isStartingZone || seed % 4 === 3;
  const hasFormation = !isStartingZone && hasEnemies && seed % 3 === 0;
  let enemies;
  let formation = null;

  if (hasFormation) {
    const formationSizes = [{ columns: 8, rows: 2 }, { columns: 8, rows: 3 }, { columns: 8, rows: 4 }];
    const size = formationSizes[(seed >>> 2) % formationSizes.length];
    const spacing = 48;
    const centerX = 480 + ((seed >>> 5) % 181) - 90;
    const centerY = 480 + ((seed >>> 9) % 181) - 90;
    enemies = Array.from({ length: size.columns * size.rows }, (_, index) => {
      const column = index % size.columns;
      const row = Math.floor(index / size.columns);
      const enemy = createEnemy(
        zoneX,
        zoneY,
        index,
        centerX + (column - (size.columns - 1) / 2) * spacing,
        centerY + (row - (size.rows - 1) / 2) * spacing,
        true,
      );
      enemy.formationColumn = column;
      enemy.formationRow = row;
      return enemy;
    });
    formation = {
      axis: seed % 2 === 0 ? "y" : "x",
      direction: seed & 1 ? 1 : -1,
      travelled: 0,
      range: 190 + (seed % 100),
      columns: size.columns,
      rows: size.rows,
    };
  } else if (hasEnemies) {
    const positions = [
      { x: 230 + (seed % 90), y: 235 + ((seed >>> 3) % 110) },
      { x: 690 - ((seed >>> 6) % 90), y: 300 + ((seed >>> 9) % 160) },
      { x: 360 + ((seed >>> 12) % 220), y: 720 - ((seed >>> 15) % 100) },
    ];
    enemies = positions.map((position, index) => createEnemy(zoneX, zoneY, index, position.x, position.y));
    if (isStartingZone) enemies[0].alive = false;
  } else {
    enemies = [];
  }

  const decor = createDecor(zoneX, zoneY, enemies);
  return {
    x: zoneX,
    y: zoneY,
    enemies,
    formation,
    decor,
    healthBonuses: createHealthBonuses(zoneX, zoneY, seed, enemies, decor),
  };
}

function getZone(game, zoneX, zoneY) {
  const key = zoneKey(zoneX, zoneY);
  if (!game.zones.has(key)) game.zones.set(key, createZone(zoneX, zoneY));
  return game.zones.get(key);
}

function getNearbyZones(game, x, y, radius = 1) {
  const centerX = worldZone(x);
  const centerY = worldZone(y);
  const zones = [];
  for (let zy = centerY - radius; zy <= centerY + radius; zy += 1) {
    for (let zx = centerX - radius; zx <= centerX + radius; zx += 1) zones.push(getZone(game, zx, zy));
  }
  return zones;
}

function facingFromVector(x, y, fallback = "down") {
  if (Math.abs(x) > Math.abs(y)) return x > 0 ? "right" : "left";
  if (Math.abs(y) > 0) return y > 0 ? "down" : "up";
  return fallback;
}

function createBullet(game, owner, x, y, facing, ownerId = null) {
  const vector = directionVectors[facing];
  game.bullets.push({
    owner,
    ownerId,
    x: x + vector.x * 20,
    y: y + vector.y * 20,
    vx: vector.x * BULLET_SPEED,
    vy: vector.y * BULLET_SPEED,
    life: 2,
    remainingDistance: owner === "player" ? TANK_SHELL_RANGE : null,
  });
}

export function createTerminalGame() {
  const game = {
    player: { x: WORLD_ZONE_SIZE / 2, y: WORLD_ZONE_SIZE / 2, facing: "up", lives: INITIAL_PLAYER_LIVES, cooldown: 0, shotAnimation: 0, animation: 0, invulnerable: 0, moving: false },
    zones: new Map(),
    bullets: [],
    impacts: [],
    explosions: [],
    planes: [],
    planeBombs: [],
    airRaidTimer: 6,
    airRaidCount: 0,
    score: 0,
    distance: 0,
    running: false,
    gameOver: false,
  };
  getNearbyZones(game, game.player.x, game.player.y);
  return game;
}

function moveFormation(zone, player, delta) {
  if (!zone.formation) return;
  const formation = zone.formation;
  const living = zone.enemies.filter((enemy) => enemy.alive);
  if (living.length <= zone.enemies.length / 2) {
    living.forEach((enemy) => { enemy.formation = false; enemy.decisionTimer = 0; });
    zone.formation = null;
    return;
  }
  const centerX = living.reduce((sum, enemy) => sum + enemy.x, 0) / living.length;
  const centerY = living.reduce((sum, enemy) => sum + enemy.y, 0) / living.length;
  const dx = player.x - centerX;
  const dy = player.y - centerY;
  const distance = Math.hypot(dx, dy);
  formation.decisionTimer = (formation.decisionTimer || 0) - delta;
  if (distance < 900 && formation.decisionTimer <= 0) {
    const closing = distance > 240;
    formation.axis = closing ? (Math.abs(dx) >= Math.abs(dy) ? "x" : "y") : (Math.abs(dx) >= Math.abs(dy) ? "y" : "x");
    formation.direction = closing ? Math.sign(formation.axis === "x" ? dx : dy) || 1 : (formation.direction || 1);
    formation.decisionTimer = 0.55;
  }
  const speed = distance < 900 ? 58 : 48;
  const movement = speed * delta * formation.direction;
  living.forEach((enemy) => {
    if (formation.axis === "x") enemy.x += movement;
    else enemy.y += movement;
    if (enemy.shotAnimation === 0) {
      enemy.facing = formation.axis === "x"
        ? (formation.direction > 0 ? "right" : "left")
        : (formation.direction > 0 ? "down" : "up");
    }
  });
  if (distance >= 900) {
    formation.travelled += Math.abs(movement);
    if (formation.travelled >= formation.range) {
      formation.travelled = 0;
      formation.direction *= -1;
    }
  }
}

function storeTankImpact(game, tileX, tileY) {
  const existing = game.impacts.find((impact) => impact.x === tileX && impact.y === tileY);
  if (!existing) {
    game.impacts.push({ x: tileX, y: tileY });
    if (game.impacts.length > 300) game.impacts.shift();
  }
}

function createTankExplosion(game, x, y, leavesImpact) {
  if (leavesImpact) {
    const tileX = Math.floor(x / TILE_SIZE) * TILE_SIZE;
    const tileY = Math.floor(y / TILE_SIZE) * TILE_SIZE;
    game.explosions.push({
      x: tileX + TILE_SIZE / 2,
      y: tileY + TILE_SIZE / 2,
      age: 0,
      pendingImpact: { x: tileX, y: tileY },
    });
    return;
  }
  game.explosions.push({ x, y, age: 0, pendingImpact: null });
}

function updateExplosions(game, delta) {
  const duration = EXPLOSION_FRAME_DURATION * EXPLOSION_FRAME_COUNT;
  game.explosions = game.explosions.filter((explosion) => {
    explosion.age += delta;
    if (explosion.age < duration) return true;
    if (explosion.pendingImpact) storeTankImpact(game, explosion.pendingImpact.x, explosion.pendingImpact.y);
    return false;
  });
}

function nextAirRaidDelay(game) {
  const seed = hashCoordinates(game.airRaidCount, Math.floor(game.distance), game.score + 1600);
  return 9 + (seed % 9);
}

function spawnFighterPlane(game) {
  const seed = hashCoordinates(game.airRaidCount, Math.round(game.player.x), Math.round(game.player.y));
  const directionNames = ["up", "right", "down", "left"];
  const direction = directionNames[seed % directionNames.length];
  const vector = directionVectors[direction];
  const horizontal = direction === "left" || direction === "right";
  const entryDistance = horizontal ? TERMINAL_WIDTH / 2 + 120 : TERMINAL_HEIGHT / 2 + 120;
  const lateralOffset = ((seed >>> 5) % 321) - 160;
  const targetX = game.player.x + (horizontal ? 0 : lateralOffset);
  const targetY = game.player.y + (horizontal ? lateralOffset : 0);
  game.planes.push({
    x: targetX - vector.x * entryDistance,
    y: targetY - vector.y * entryDistance,
    vx: vector.x * PLANE_SPEED,
    vy: vector.y * PLANE_SPEED,
    direction,
    dropTimer: entryDistance / PLANE_SPEED,
    dropped: false,
    life: (entryDistance * 2 + 300) / PLANE_SPEED,
  });
  game.airRaidCount += 1;
  game.airRaidTimer = nextAirRaidDelay(game);
}

export function planeBombSize(bomb) {
  const progress = Math.max(0, Math.min(1, bomb.age / PLANE_BOMB_DURATION));
  return 28 - progress * 22;
}

function updateAirRaids(game, delta) {
  game.airRaidTimer -= delta;
  if (game.airRaidTimer <= 0) spawnFighterPlane(game);

  game.planes = game.planes.filter((plane) => {
    plane.x += plane.vx * delta;
    plane.y += plane.vy * delta;
    plane.dropTimer -= delta;
    plane.life -= delta;
    if (!plane.dropped && plane.dropTimer <= 0) {
      plane.dropped = true;
      game.planeBombs.push({ x: plane.x, y: plane.y, age: 0 });
    }
    return plane.life > 0;
  });

  game.planeBombs = game.planeBombs.filter((bomb) => {
    bomb.age += delta;
    if (bomb.age < PLANE_BOMB_DURATION) return true;
    createTankExplosion(game, bomb.x, bomb.y, true);
    return false;
  });
}

function incomingPlayerShot(enemy, bullets) {
  return bullets.find((bullet) => {
    if (bullet.owner !== "player") return false;
    const directionX = Math.sign(bullet.vx);
    const directionY = Math.sign(bullet.vy);
    const ahead = (enemy.x - bullet.x) * directionX + (enemy.y - bullet.y) * directionY;
    const lateral = Math.abs((enemy.x - bullet.x) * directionY - (enemy.y - bullet.y) * directionX);
    return ahead > 0 && ahead < 150 && lateral < 25;
  });
}

function chooseSoloMovement(enemy, player, allies, incomingShot) {
  const dx = player.x - enemy.x;
  const dy = player.y - enemy.y;
  const distance = Math.hypot(dx, dy);
  const nearbyAllies = allies.filter((ally) => ally !== enemy && ally.alive && Math.hypot(ally.x - enemy.x, ally.y - enemy.y) < 360);
  const dominantHorizontal = Math.abs(dx) >= Math.abs(dy);
  const towardHorizontal = dx >= 0 ? "right" : "left";
  const towardVertical = dy >= 0 ? "down" : "up";
  const awayHorizontal = dx >= 0 ? "left" : "right";
  const awayVertical = dy >= 0 ? "up" : "down";

  if (incomingShot) {
    enemy.behavior = "dodge";
    enemy.moveDirection = incomingShot.vx !== 0
      ? (enemy.strafeDirection > 0 ? "down" : "up")
      : (enemy.strafeDirection > 0 ? "right" : "left");
  } else if (enemy.blockedShot) {
    enemy.behavior = "strafe";
    enemy.moveDirection = dominantHorizontal
      ? (enemy.strafeDirection > 0 ? "down" : "up")
      : (enemy.strafeDirection > 0 ? "right" : "left");
  } else if (distance > 760) {
    enemy.behavior = "patrol";
    if (enemy.patrolAxis === "x") enemy.moveDirection = enemy.patrolDirection > 0 ? "right" : "left";
    else enemy.moveDirection = enemy.patrolDirection > 0 ? "down" : "up";
  } else if (nearbyAllies.length > 0 && distance > 180 && distance < 600 && enemy.id.charCodeAt(enemy.id.length - 1) % 3 !== 0) {
    const side = enemy.strafeDirection;
    const flankX = player.x + (dominantHorizontal ? 0 : side * 95);
    const flankY = player.y + (dominantHorizontal ? side * 95 : 0);
    const flankDx = flankX - enemy.x;
    const flankDy = flankY - enemy.y;
    enemy.behavior = "flank";
    enemy.moveDirection = Math.abs(flankDx) >= Math.abs(flankDy)
      ? (flankDx >= 0 ? "right" : "left")
      : (flankDy >= 0 ? "down" : "up");
  } else if (distance > 310) {
    enemy.behavior = "chase";
    enemy.moveDirection = dominantHorizontal ? towardHorizontal : towardVertical;
  } else if (distance < 145) {
    enemy.behavior = "retreat";
    enemy.moveDirection = dominantHorizontal ? awayHorizontal : awayVertical;
  } else if (Math.min(Math.abs(dx), Math.abs(dy)) > 52) {
    enemy.behavior = "align";
    enemy.moveDirection = Math.abs(dx) < Math.abs(dy) ? towardHorizontal : towardVertical;
  } else {
    enemy.behavior = "strafe";
    if (dominantHorizontal) enemy.moveDirection = enemy.strafeDirection > 0 ? "down" : "up";
    else enemy.moveDirection = enemy.strafeDirection > 0 ? "right" : "left";
  }
}

function moveSoloEnemy(enemy, player, allies, bullets, delta) {
  const incomingShot = incomingPlayerShot(enemy, bullets);
  if (incomingShot && enemy.behavior !== "dodge") enemy.decisionTimer = 0;
  enemy.decisionTimer -= delta;
  if (enemy.decisionTimer <= 0) {
    const seed = hashCoordinates(Math.round(enemy.x), Math.round(enemy.y), Math.round(player.x + player.y));
    enemy.decisionTimer = incomingShot ? 0.22 : 0.45 + (seed % 45) / 100;
    if (seed % 3 === 0) enemy.strafeDirection *= -1;
    if (seed % 5 === 0) enemy.patrolDirection *= -1;
    chooseSoloMovement(enemy, player, allies, incomingShot);
  }

  const direction = directionVectors[enemy.moveDirection] || directionVectors.down;
  const speeds = { patrol: 38, chase: 56, retreat: 66, align: 48, strafe: 52, flank: 60, dodge: 92 };
  const speed = speeds[enemy.behavior] * (enemy.shotAnimation > 0 ? 0.35 : 1);
  enemy.x += direction.x * speed * delta;
  enemy.y += direction.y * speed * delta;
  if (enemy.shotAnimation === 0) enemy.facing = enemy.moveDirection;
}

function allyBlocksShot(enemy, player, facing, allies) {
  const vector = directionVectors[facing];
  const startX = enemy.x + vector.x * 20;
  const startY = enemy.y + vector.y * 20;
  const playerDistance = (player.x - startX) * vector.x + (player.y - startY) * vector.y;
  return allies.some((ally) => {
    if (!ally.alive || ally === enemy) return false;
    const ahead = (ally.x - startX) * vector.x + (ally.y - startY) * vector.y;
    const sideways = Math.abs((ally.x - startX) * vector.y - (ally.y - startY) * vector.x);
    return ahead > -ENEMY_SIZE / 2 && ahead < playerDistance - 17 && sideways < ENEMY_SIZE / 2 + ENEMY_BULLET_SIZE / 2 + 2;
  });
}

function updateEnemies(game, delta) {
  const player = game.player;
  const zones = getNearbyZones(game, player.x, player.y);
  const allies = zones.flatMap((zone) => zone.enemies).filter((enemy) => enemy.alive);
  zones.forEach((zone) => {
    moveFormation(zone, player, delta);
    zone.enemies.forEach((enemy) => {
      if (!enemy.alive) return;
      enemy.cooldown = Math.max(0, enemy.cooldown - delta);
      enemy.shotAnimation = Math.max(0, enemy.shotAnimation - delta);
      if (!enemy.formation) moveSoloEnemy(enemy, player, allies, game.bullets, delta);
      const dx = player.x - enemy.x;
      const dy = player.y - enemy.y;
      const distance = Math.hypot(dx, dy);
      if (distance < 470 && Math.min(Math.abs(dx), Math.abs(dy)) < 18 && enemy.cooldown === 0) {
        const firingDirection = facingFromVector(dx, dy, enemy.facing);
        if (allyBlocksShot(enemy, player, firingDirection, allies)) {
          enemy.blockedShot = true;
          enemy.decisionTimer = 0;
          return;
        }
        enemy.blockedShot = false;
        enemy.facing = firingDirection;
        createBullet(game, "enemy", enemy.x, enemy.y, enemy.facing, enemy.id);
        enemy.shotAnimation = 0.24;
        enemy.cooldown = 1.25 + (hashCoordinates(Math.round(enemy.x), Math.round(enemy.y), game.score) % 80) / 100;
      }
    });
  });
}

function killEnemy(game, enemy, awardScore = true) {
  if (!enemy.alive) return;
  enemy.alive = false;
  enemy.corpse = true;
  if (awardScore) game.score += 100;
}

function segmentHit(startX, startY, endX, endY, targetX, targetY, radius) {
  const dx = endX - startX;
  const dy = endY - startY;
  const lengthSquared = dx * dx + dy * dy;
  const position = lengthSquared === 0 ? 0 : Math.max(0, Math.min(1, ((targetX - startX) * dx + (targetY - startY) * dy) / lengthSquared));
  const differenceX = startX + dx * position - targetX;
  const differenceY = startY + dy * position - targetY;
  return differenceX * differenceX + differenceY * differenceY < radius * radius ? position : null;
}

function updateBullets(game, delta) {
  const player = game.player;
  game.bullets = game.bullets.filter((bullet) => {
    const startX = bullet.x;
    const startY = bullet.y;
    const fullStepX = bullet.vx * delta;
    const fullStepY = bullet.vy * delta;
    const fullStepDistance = Math.hypot(fullStepX, fullStepY);
    const travelRatio = bullet.remainingDistance !== null && bullet.remainingDistance !== undefined && bullet.remainingDistance < fullStepDistance
      ? bullet.remainingDistance / fullStepDistance
      : 1;
    bullet.x += fullStepX * travelRatio;
    bullet.y += fullStepY * travelRatio;
    if (bullet.remainingDistance !== null && bullet.remainingDistance !== undefined) {
      bullet.remainingDistance -= fullStepDistance * travelRatio;
    }
    bullet.life -= delta;

    let firstHit = null;
    const zones = getNearbyZones(game, bullet.x, bullet.y);
    for (const zone of zones) {
      for (const enemy of zone.enemies) {
        if (!enemy.alive || enemy.id === bullet.ownerId) continue;
        const position = segmentHit(startX, startY, bullet.x, bullet.y, enemy.x, enemy.y, bullet.owner === "player" ? 14 : 11);
        if (position !== null && (!firstHit || position < firstHit.position)) firstHit = { target: enemy, position };
      }
    }
    if (bullet.owner === "enemy") {
      const position = segmentHit(startX, startY, bullet.x, bullet.y, player.x, player.y, 17);
      if (position !== null && (!firstHit || position < firstHit.position)) firstHit = { target: player, position };
    }
    if (!firstHit) return true;
    if (firstHit.target !== player) {
      if (bullet.owner === "player") {
        createTankExplosion(game, firstHit.target.x, firstHit.target.y, false);
      }
      killEnemy(game, firstHit.target, bullet.owner === "player");
    } else if (player.invulnerable === 0) {
      player.lives -= 1;
      player.invulnerable = 1.2;
      if (player.lives <= 0) { game.running = false; game.gameOver = true; }
    }
    return false;
  });

  game.bullets = game.bullets.filter((bullet) => {
    const expired = bullet.life <= 0 || (bullet.remainingDistance !== null && bullet.remainingDistance !== undefined && bullet.remainingDistance <= 0);
    if (expired && bullet.owner === "player") createTankExplosion(game, bullet.x, bullet.y, true);
    return !expired;
  });
}

function eliminateRunOverEnemies(game) {
  getNearbyZones(game, game.player.x, game.player.y).forEach((zone) => zone.enemies.forEach((enemy) => {
    if (!enemy.alive || Math.hypot(enemy.x - game.player.x, enemy.y - game.player.y) >= 28) return;
    killEnemy(game, enemy);
  }));
}

function crushDecor(game) {
  getNearbyZones(game, game.player.x, game.player.y).forEach((zone) => zone.decor.forEach((item) => {
    if (item.crushed || item.asset.startsWith("decorFlaque")) return;
    const centerX = item.x + TILE_SIZE / 2;
    const centerY = item.y + TILE_SIZE / 2;
    if (Math.abs(centerX - game.player.x) < 28 && Math.abs(centerY - game.player.y) < 28) item.crushed = true;
  }));
}

function collectHealthBonuses(game) {
  getNearbyZones(game, game.player.x, game.player.y).forEach((zone) => zone.healthBonuses.forEach((bonus) => {
    if (bonus.collected || Math.hypot(bonus.x - game.player.x, bonus.y - game.player.y) >= 30) return;
    bonus.collected = true;
    game.player.lives += 1;
  }));
}

export function updateTerminalGame(game, delta, input = {}) {
  if (!game.running) return;
  updateExplosions(game, delta);
  updateAirRaids(game, delta);
  const player = game.player;
  player.cooldown = Math.max(0, player.cooldown - delta);
  player.shotAnimation = Math.max(0, player.shotAnimation - delta);
  player.invulnerable = Math.max(0, player.invulnerable - delta);

  let moveX = input.x || 0;
  let moveY = input.y || 0;
  if (moveX && moveY) {
    if (player.facing === "left" || player.facing === "right") moveY = 0;
    else moveX = 0;
  }
  player.moving = Boolean(moveX || moveY);
  if (moveX || moveY) player.facing = facingFromVector(moveX, moveY, player.facing);
  player.x += moveX * PLAYER_SPEED * delta;
  player.y += moveY * PLAYER_SPEED * delta;
  if (moveX || moveY) { player.animation += delta; game.distance += PLAYER_SPEED * delta; }
  crushDecor(game);
  collectHealthBonuses(game);
  eliminateRunOverEnemies(game);

  if (input.shoot && player.cooldown === 0) {
    createBullet(game, "player", player.x, player.y, player.facing);
    player.cooldown = 0.28;
    player.shotAnimation = 0.28;
  }
  updateEnemies(game, delta);
  updateBullets(game, delta);
}

function drawSheetFrame(ctx, image, frame, x, y, size = 44, columns = 2) {
  const sourceX = (frame % columns) * 32;
  const sourceY = Math.floor(frame / columns) * 32;
  ctx.drawImage(image, sourceX, sourceY, 32, 32, Math.round(x - size / 2), Math.round(y - size / 2), size, size);
}

function isVisible(x, y, cameraX, cameraY, margin = 48) {
  return x > cameraX - margin && y > cameraY - margin && x < cameraX + TERMINAL_WIDTH + margin && y < cameraY + TERMINAL_HEIGHT + margin;
}

export function playerShotAssetName(player) {
  const direction = `${player.facing[0].toUpperCase()}${player.facing.slice(1)}`;
  return `playerShot${player.moving ? "Run" : ""}${direction}`;
}

export function drawTerminalGame(ctx, game, assets) {
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = COLORS.dark;
  ctx.fillRect(0, 0, TERMINAL_WIDTH, TERMINAL_HEIGHT);
  if (!assets) return;

  const cameraX = game.player.x - TERMINAL_WIDTH / 2;
  const cameraY = game.player.y - TERMINAL_HEIGHT / 2;
  const zones = getNearbyZones(game, game.player.x, game.player.y);

  const firstTileX = Math.floor(cameraX / TILE_SIZE);
  const firstTileY = Math.floor(cameraY / TILE_SIZE);
  const lastTileX = Math.ceil((cameraX + TERMINAL_WIDTH) / TILE_SIZE);
  const lastTileY = Math.ceil((cameraY + TERMINAL_HEIGHT) / TILE_SIZE);
  for (let tileY = firstTileY; tileY <= lastTileY; tileY += 1) {
    for (let tileX = firstTileX; tileX <= lastTileX; tileX += 1) {
      ctx.drawImage(assets.tileBlank, Math.floor(tileX * TILE_SIZE - cameraX), Math.floor(tileY * TILE_SIZE - cameraY), TILE_SIZE, TILE_SIZE);
    }
  }

  game.impacts.forEach((impact) => {
    if (!isVisible(impact.x + TILE_SIZE / 2, impact.y + TILE_SIZE / 2, cameraX, cameraY, TILE_SIZE)) return;
    ctx.drawImage(assets.tankImpact, Math.round(impact.x - cameraX), Math.round(impact.y - cameraY), TILE_SIZE, TILE_SIZE);
  });

  zones.forEach((zone) => zone.decor.forEach((item) => {
    if (!isVisible(item.x + 16, item.y + 16, cameraX, cameraY, 32)) return;
    ctx.drawImage(assets[item.crushed ? "debris" : item.asset], Math.round(item.x - cameraX), Math.round(item.y - cameraY), TILE_SIZE, TILE_SIZE);
  }));

  const continuousAnimation = typeof performance === "undefined" ? 0 : performance.now() / 1000;
  zones.forEach((zone) => zone.healthBonuses.forEach((bonus) => {
    if (bonus.collected || !isVisible(bonus.x, bonus.y, cameraX, cameraY)) return;
    const frame = Math.floor(continuousAnimation * 7) % 6;
    drawSheetFrame(ctx, assets.healthBonus, frame, bonus.x - cameraX, bonus.y - cameraY, 32, 2);
  }));

  zones.forEach((zone) => zone.enemies.forEach((enemy) => {
    if (!enemy.corpse || !isVisible(enemy.x, enemy.y, cameraX, cameraY)) return;
    ctx.drawImage(
      assets.corpse,
      Math.round(enemy.x - cameraX - ENEMY_SIZE / 2),
      Math.round(enemy.y - cameraY - ENEMY_SIZE / 2),
      ENEMY_SIZE,
      ENEMY_SIZE,
    );
  }));

  zones.forEach((zone) => zone.enemies.forEach((enemy) => {
    if (!enemy.alive || !isVisible(enemy.x, enemy.y, cameraX, cameraY)) return;
    const image = assets[`enemy${enemy.facing[0].toUpperCase()}${enemy.facing.slice(1)}`];
    const horizontal = enemy.facing === "left" || enemy.facing === "right";
    const columns = horizontal ? 3 : 2;
    const frameCount = horizontal ? 9 : 3;
    const frame = Math.floor(continuousAnimation * 8 + (hashCoordinates(Math.round(enemy.x), Math.round(enemy.y), 91) % frameCount)) % frameCount;
    drawSheetFrame(ctx, image, frame, enemy.x - cameraX, enemy.y - cameraY, ENEMY_SIZE, columns);
  }));

  game.bullets.forEach((bullet) => {
    const size = bullet.owner === "enemy" ? ENEMY_BULLET_SIZE : 14;
    ctx.drawImage(assets.bullet, Math.round(bullet.x - cameraX - size / 2), Math.round(bullet.y - cameraY - size / 2), size, size);
  });

  game.explosions.forEach((explosion) => {
    if (!isVisible(explosion.x, explosion.y, cameraX, cameraY, 32)) return;
    const frame = Math.min(EXPLOSION_FRAME_COUNT - 1, Math.floor(explosion.age / EXPLOSION_FRAME_DURATION));
    drawSheetFrame(ctx, assets.tankExplosion, frame, explosion.x - cameraX, explosion.y - cameraY, 32, 2);
  });

  const player = game.player;
  if (player.invulnerable === 0 || Math.floor(player.invulnerable * 12) % 2 === 0) {
    const screenX = player.x - cameraX;
    const screenY = player.y - cameraY;
    if (player.shotAnimation > 0) {
      const frame = Math.min(6, Math.floor((0.28 - player.shotAnimation) / 0.04));
      const name = playerShotAssetName(player);
      drawSheetFrame(ctx, assets[name], frame, screenX, screenY, 44, 3);
    } else {
      const frame = Math.floor(player.animation * 8) % 3;
      const name = `player${player.facing[0].toUpperCase()}${player.facing.slice(1)}`;
      drawSheetFrame(ctx, assets[name], frame, screenX, screenY, 44, 2);
    }
  }

  game.planeBombs.forEach((bomb) => {
    if (!isVisible(bomb.x, bomb.y, cameraX, cameraY, 40)) return;
    const size = planeBombSize(bomb);
    ctx.drawImage(assets.fighterPlaneShell, Math.round(bomb.x - cameraX - size / 2), Math.round(bomb.y - cameraY - size / 2), size, size);
  });

  game.planes.forEach((plane) => {
    if (!isVisible(plane.x, plane.y, cameraX, cameraY, 100)) return;
    const angles = { up: 0, right: Math.PI / 2, down: Math.PI, left: -Math.PI / 2 };
    ctx.save();
    ctx.translate(Math.round(plane.x - cameraX), Math.round(plane.y - cameraY));
    ctx.rotate(angles[plane.direction]);
    ctx.drawImage(assets.fighterPlane, -16, -32, 32, 64);
    ctx.restore();
  });

  if (!game.running) {
    ctx.fillStyle = COLORS.dark;
    ctx.fillRect(TERMINAL_WIDTH / 2 - 235, TERMINAL_HEIGHT / 2 - 58, 470, 116);
    ctx.strokeStyle = COLORS.light;
    ctx.lineWidth = 2;
    ctx.strokeRect(TERMINAL_WIDTH / 2 - 235, TERMINAL_HEIGHT / 2 - 58, 470, 116);
    ctx.fillStyle = COLORS.light;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = "700 25px monospace";
    ctx.fillText(game.gameOver ? "MISSION TERMINÉE" : "SURVIE INFINIE", TERMINAL_WIDTH / 2, TERMINAL_HEIGHT / 2 - 14);
    ctx.font = "14px monospace";
    ctx.fillText(game.gameOver ? `Score : ${game.score}` : "Avancez. Survivez. Détruisez.", TERMINAL_WIDTH / 2, TERMINAL_HEIGHT / 2 + 24);
    ctx.textAlign = "start";
  }
}
