import decorFlaque2 from "./assets/decor/flaque2.png";
import decorFlaque3 from "./assets/decor/flaque3.png";
import decorMitrailletteDroite from "./assets/decor/mitraillette_droite.png";
import decorMitrailletteGauche from "./assets/decor/mitraillette_gauche.png";
import enemyDown from "./assets/soldat_walk_bas.png";
import enemyLeft from "./assets/soldat_walk_left.png";
import enemyRight from "./assets/soldat_walk_right.png";
