import playerShotRunLeft from "./assets/new_sprites/player_shot_left_run.png";
import playerShotRunRight from "./assets/new_sprites/player_shot_right_run.png";
import playerShotRunUp from "./assets/new_sprites/player_shot_up_run.png";

const sources = {
  bullet,
  tankExplosion,
  tankImpact,
  fighterPlane,
  fighterPlaneShell,
  healthBonus,
  tileBlank,
  decorBarbelerHorizontal,
  decorBarbelerVertical,
  decorBlocAntichar,
  corpse,
  debris,
  decorFlaque1,
  decorFlaque2,
  decorFlaque3,
  decorMitrailletteDroite,
  decorMitrailletteGauche,
  enemyDown,
  enemyLeft,
  enemyRight,
  enemyUp,
  playerDown,
  playerLeft,
  playerRight,
  playerUp,
  playerShotDown,
  playerShotLeft,
  playerShotRight,
  playerShotUp,
  playerShotRunDown,
  playerShotRunLeft,
  playerShotRunRight,
  playerShotRunUp,
};

export function loadTerminalAssets() {
  return Promise.all(Object.entries(sources).map(([name, source]) => new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve([name, image]);
    image.onerror = reject;
    image.src = source;
  }))).then((entries) => Object.fromEntries(entries));
}
